def bubble_sort(nums):
    result = list(nums)
    n = len(result)
    for i in range(n - 1):
        swapped = False
        for j in range(n - 1 - i):
            if result[j] > result[j + 1]:
                result[j], result[j + 1] = result[j + 1], result[j]
                swapped = True
        if not swapped:
            break
    return result

data = [5, 2, 9, 1, 5, 6]
print(bubble_sort(data))
print(data)
print(bubble_sort([]))
